using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 readonly Vector3[] dungeonRecords={new(3.6f,0,0),new(23,0,-1),new(-4.5f,0,-25)};
 readonly int[] dungeonRecordKinds={2,4,5};
 bool StoryAllowed(ExpeditionStorySite s){if(InCrashLot(s.X,s.Z)||InCheckpointLot(s.X,s.Z)||InBirthdayLot(s.X,s.Z)||InLetterLot(s.X,s.Z)||InFeverLot(s.X,s.Z)||InWoodlandCamp(s.X,s.Z)||InFamilyLot(s.X,s.Z)||!game.World.Playable(s.X,s.Z))return false;foreach(var d in ExpeditionDungeon.Nearby(game.World,s.X,s.Z))if(ExpeditionGame.Distance(s.X,s.Z,d.X,d.Z)<16)return false;foreach(var p in game.Building.Pieces)if(ExpeditionGame.Distance(s.X,s.Z,p.X,p.Z)<9)return false;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){double px=s.X+x*5,pz=s.Z+z*5,bx=Math.Floor(px/32)*32+16,bz=Math.Floor(pz/32)*32+16;if(!game.World.Playable(px,pz)||Math.Abs(game.World.Height(px,pz)-game.World.Height(s.X,s.Z))>1.8||game.World.BuildingCell(bx,bz)&&Math.Abs(px-bx)<game.World.BuildingHalf(bx,bz)+1&&Math.Abs(pz-bz)<game.World.BuildingHalf(bx,bz)+1)return false;}return !props.Any(p=>(p.Kind==0||p.Kind==7)&&Distance(p.Position,Ground(s.X,s.Z))<5);}
 double storyScanDue;int storyScanX=int.MinValue,storyScanZ=int.MinValue,storyScanSeed;
 void SpawnStorySites(bool force=false){int cx=(int)Math.Floor(player.Position.X/160),cz=(int)Math.Floor(player.Position.Z/160);if(!force&&game.Clock<storyScanDue&&cx==storyScanX&&cz==storyScanZ&&storyScanSeed==game.Save.Seed)return;storyScanDue=game.Clock+.75;storyScanX=cx;storyScanZ=cz;storyScanSeed=game.Save.Seed;foreach(var s in ExpeditionStorySite.Nearby(game.World,player.Position.X,player.Position.Z)){string id=s.Id+"/note";if(Distance(player.Position,Ground(s.X,s.Z))>190||uniqueObjects.Contains(id)||!StoryAllowed(s))continue;uniqueObjects.Add(id);var n=new Node3D{Name="Story_"+s.Kind,Position=Ground(s.X,s.Z),RotationDegrees=new(0,(float)s.Yaw,0)};n.SetMeta("story_kind",s.Kind);worldRoot.AddChild(n);DressStorySite(n,s);var note=n.ToGlobal(new Vector3(-2.6f,0,-2));props.Add(new WorldProp{Id=id,Kind=8,Material=s.Kind,Position=note,Node=n});
   if(s.Kind is 1 or 5){if(uniqueObjects.Add(s.Id)){var car=new Node3D{Position=n.Position,Rotation=n.Rotation};worldRoot.AddChild(car);bool burned=game.World.Changes.Burned(s.Id);ArtWreck(car,burned);PhysicsObstacle(car,new BoxShape3D{Size=new(2.1f,1.5f,4.2f)},new(0,.75f,0));props.Add(new WorldProp{Id=s.Id,Kind=2,Position=car.Position,Node=car,Hp=burned?0:100});}}
  }}
 void StoryPaper(Node3D n,Vector3 p){Box(n,p,new(.35f,.012f,.25f),new(.72f,.68f,.54f));for(int i=0;i<4;i++)Box(n,p+new Vector3(0,.008f,-.07f+i*.04f),new(.24f,.003f,.008f),new(.26f,.25f,.21f));}
 void DressStorySite(Node3D n,ExpeditionStorySite s){var canvas=new Color(.35f,.36f,.28f);var metal=new Color(.29f,.34f,.32f);
  if(s.Kind==0){ArtCamp(n);PhysicsObstacle(n,new BoxShape3D{Size=new(3.6f,1.7f,2.8f)},new(0,.85f,0));}
  if(s.Kind is 1 or 5){Bevel(n,new(2.3f,.28f,1.1f),new(.65f,.56f,.85f),Wood);Box(n,new(2.5f,.06f,-1.2f),new(.9f,.12f,1.2f),Cloth);if(s.Kind==5){for(int i=-2;i<=2;i++){Box(n,new(i*1.1f,.55f,4),new(.9f,1.1f,.6f),new(.40f,.38f,.30f),true);Box(n,new(i*1.1f,.75f,3.68f),new(.75f,.12f,.025f),new(.63f,.51f,.24f));}Tube(n,new(-3,0,3),new(-3,2.7f,3),.06f,Steel);var label=new Label3D{Text="EVACUATION / CLOSED",Position=new(-3,2.1f,3),FontSize=24,PixelSize=.008f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled};n.AddChild(label);}}
  if(s.Kind==2){for(int i=-1;i<=1;i++){Box(n,new(i*2,.50f,0),new(1.3f,.15f,2.4f),metal,true);Box(n,new(i*2,.65f,0),new(1.2f,.18f,2.25f),canvas);Box(n,new(i*2,.80f,-.65f),new(1.05f,.16f,.60f),new(.57f,.55f,.44f));for(int sign=-1;sign<=1;sign+=2)Tube(n,new(i*2+sign*.5f,0,0),new(i*2+sign*.5f,.5f,0),.035f,Steel);}Box(n,new(3.7f,.75f,.8f),new(.9f,1.5f,.7f),metal,true);}
  if(s.Kind==3){for(int i=0;i<5;i++){float x=i%3*1.6f-1.6f,z=i/3*2;Box(n,new(x,.025f,z),new(1,.05f,1.6f),new(.29f,.25f,.18f));Box(n,new(x,.45f,z-.65f),new(.4f,.9f,.14f),new(.43f,.43f,.36f),true);Box(n,new(x,.65f,z-.74f),new(.18f,.04f,.015f),Ink);}for(int i=0;i<3;i++)Ellipsoid(n,new(2.7f+i*.15f,.08f,1),new(.08f,.08f,.08f),new(.53f,.47f,.29f));}
  if(s.Kind==4){Box(n,new(3.8f,1.15f,0),new(.2f,2.3f,4),canvas,true);Box(n,new(1.4f,1.15f,-2),new(4.8f,2.3f,.2f),canvas,true);for(int i=0;i<5;i++){var beam=Box(n,new(-.7f+i*.8f,1.8f-i*.12f,0),new(.14f,.18f,3.6f),Wood);beam.RotationDegrees=new(0,0,8);}Box(n,new(2,.75f,0),new(1.3f,1.5f,2),metal,true);Box(n,new(-1,.1f,1),new(1.4f,.2f,.8f),Cloth);}
  Bevel(n,new(-2.6f,.25f,-2),new(.76f,.5f,.48f),Wood);StoryPaper(n,new(-2.6f,.51f,-2));Bevel(n,new(-2.12f,.23f,-2),new(.16f,.46f,.16f),Steel);n.AddChild(new OmniLight3D{Position=new(-2.12f,.55f,-2),LightColor=new(1,.65f,.29f),LightEnergy=.6f,OmniRange=4,DistanceFadeEnabled=true,DistanceFadeBegin=35,DistanceFadeLength=15});
 }
 bool StoryObstacle(double x,double z){foreach(var p in props)if(p.Kind==8&&p.Node.HasMeta("story_kind")){var q=p.Node.ToLocal(Ground(x,z));int kind=p.Node.GetMeta("story_kind").AsInt32();if(kind==0&&Math.Abs(q.X)<1.9&&Math.Abs(q.Z)<1.5||kind==2&&Math.Abs(q.X)<3&&Math.Abs(q.Z)<1.35||kind==4&&(Math.Abs(q.X-3.8)<.5&&Math.Abs(q.Z)<2.3||Math.Abs(q.Z+2)<.5&&q.X>-1.3&&q.X<4.1||Math.Abs(q.X-2)<.9&&Math.Abs(q.Z)<1.2)||kind==5&&Math.Abs(q.X)<2.9&&Math.Abs(q.Z-4)<.65)return true;}return false;}
 void ReadStory(int kind,string id){if(kind<0||kind>=6)return;if(!game.Change(()=>{if(!game.Profile.Journal.Seen.Contains(id))game.Profile.Journal.Seen.Add(id);game.AwardResearch("discovery/manual/"+kind,25);}))return;if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopStoryLetter),kind);else ShowLetter(kind);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopStoryLetter(int kind){if(CoopClient&&kind>=0&&kind<6){ShowLetter(kind);coopCheckLetterShown=true;}}
 bool ReadDungeonRecord(){for(int i=0;i<3;i++)if(Distance(player.Position,dungeonRecords[i])<2.5){ReadStory(dungeonRecordKinds[i],$"{game.Save.Seed}/vault/{dungeon.Id}/note/{dungeonRecordKinds[i]}");return true;}return false;}
 void DressDungeonRecords(){for(int i=0;i<3;i++){var p=dungeonRecords[i];if(i>0)Box(dungeonRoot,p+new Vector3(0,.35f,0),new(.8f,.7f,.6f),Wood,true);StoryPaper(dungeonRoot,p+new Vector3(0,i==0?.98f:.72f,0));}for(int i=0;i<2;i++){float z=-2-i*4;Box(dungeonRoot,new(24.3f,.5f,z),new(1.2f,.20f,2),Steel,true);Box(dungeonRoot,new(24.3f,.67f,z),new(1.15f,.16f,1.9f),Cloth);Box(dungeonRoot,new(24.3f,.80f,z-.55f),new(1,.12f,.6f),new(.55f,.54f,.43f));}Box(dungeonRoot,new(25.4f,1.1f,-8),new(.45f,2.2f,1.4f),Steel,true);for(int i=0;i<4;i++)Box(dungeonRoot,new(25.1f,.3f+i*.45f,-8),new(.65f,.05f,1.3f),Wood);}
}
